/* VOCE visual guides. Editorial summaries of the existing public frameworks. */
(() => {
  'use strict';
  const UI = {
    en:{open:'Understand with a diagram',close:'Close',kicker:'VOCE · Visual guide',human:'Human responsibility',source:'VOCE editorial summary · 11 October 2026 · The full framework remains the reference.',proof:'What supports a control?',states:[['Absent','No reliable evidence.'],['Declared','An assertion without adequate supporting evidence.'],['Documented','A current policy, configuration or architecture record.'],['Tested','A defined test with a recorded result.'],['Verified in operation','Current evidence from the deployed environment.']]},
    fr:{open:'Comprendre en schéma',close:'Fermer',kicker:'VOCE · Guide visuel',human:'Responsabilité humaine',source:'Synthèse éditoriale VOCE · 11 octobre 2026 · Le référentiel complet reste la référence.',proof:'Qu’est-ce qui étaye un contrôle?',states:[['Absent','Aucune preuve fiable.'],['Déclaré','Une affirmation sans preuve suffisante.'],['Documenté','Une politique, configuration ou architecture à jour.'],['Testé','Un test défini avec un résultat consigné.'],['Vérifié en fonctionnement','Des preuves actuelles dans l’environnement déployé.']]},
    it:{open:'Capire con uno schema',close:'Chiudi',kicker:'VOCE · Guida visiva',human:'Responsabilità umana',source:'Sintesi editoriale VOCE · 11 ottobre 2026 · Il quadro completo resta il riferimento.',proof:'Che cosa dimostra un controllo?',states:[['Assente','Nessuna evidenza affidabile.'],['Dichiarato','Un’affermazione senza evidenze sufficienti.'],['Documentato','Una policy, configurazione o architettura aggiornata.'],['Testato','Un test definito con un risultato registrato.'],['Verificato in esercizio','Evidenze attuali nell’ambiente operativo.']]}
  };
  const GUIDES = {
    infrastructure:{type:'levels',
      en:{title:'What can an AI agent do?',intro:'The VOCE A0–A4 reference distinguishes the scope of action and the controls to examine. These are operational categories, not a numerical performance scale.',stages:[
        ['Assistant','Generates or retrieves information without external action.','Review the answers and their sources.'],
        ['Connected tools','Uses approved tools for reading or low-impact tasks.','Limit access and ensure it can be revoked.'],
        ['Delegated action','Performs business actions within a defined mandate.','Set transaction limits, approvals and recovery procedures.'],
        ['Multi-agent system','Coordinates agents, models and tools across systems.','Trace the delegation chain and evaluate shared outcomes.'],
        ['Critical network','Operates in contexts with potentially critical consequences.','Assign an accountable owner and test emergency intervention.']
      ],boundary:'A4 describes criticality; it does not mean self-improvement. The appropriate category depends on the use case. These levels belong to the VOCE reference and are not an EU certification.',actions:[['Review the controls','agent-conformance'],['Read the complete A0–A4 reference','agent-infrastructure#maturity']]},
      fr:{title:'Que peut faire un agent IA?',intro:'Le référentiel VOCE A0–A4 distingue le périmètre d’action et les contrôles à examiner. Il décrit des catégories d’exploitation, sans mesurer la performance sur une échelle numérique.',stages:[
        ['Assistant','Génère ou recherche de l’information sans action externe.','Revoir les réponses et leurs sources.'],
        ['Outils connectés','Utilise des outils approuvés en lecture ou à faible impact.','Limiter les accès et pouvoir les révoquer.'],
        ['Action déléguée','Exécute des actions métier dans un mandat défini.','Fixer les limites transactionnelles, les validations et les procédures de retour arrière.'],
        ['Système multi-agents','Coordonne des agents, modèles et outils entre systèmes.','Tracer la chaîne de délégation et évaluer les résultats communs.'],
        ['Réseau critique','Opère dans des contextes aux conséquences potentiellement critiques.','Désigner un responsable et tester l’intervention d’urgence.']
      ],boundary:'A4 décrit la criticité; il ne signifie pas auto-amélioration. La catégorie appropriée dépend de l’usage. Ces niveaux sont propres au référentiel VOCE et ne constituent pas une certification européenne.',actions:[['Examiner les contrôles','agent-conformance'],['Lire le référentiel A0–A4 complet','agent-infrastructure#maturity']]},
      it:{title:'Che cosa può fare un agente IA?',intro:'Il riferimento VOCE A0–A4 distingue il perimetro d’azione e i controlli da esaminare. Descrive categorie operative, senza misurare le prestazioni su una scala numerica.',stages:[
        ['Assistente','Genera o cerca informazioni senza azioni esterne.','Rivedere le risposte e le loro fonti.'],
        ['Strumenti connessi','Usa strumenti approvati in lettura o a basso impatto.','Limitare gli accessi e poterli revocare.'],
        ['Azione delegata','Esegue azioni operative entro un mandato definito.','Definire limiti di transazione, approvazioni e procedure di ripristino.'],
        ['Sistema multi-agente','Coordina agenti, modelli e strumenti tra sistemi.','Tracciare la catena di delega e valutare i risultati comuni.'],
        ['Rete critica','Opera in contesti con conseguenze potenzialmente critiche.','Designare un responsabile e testare l’intervento d’emergenza.']
      ],boundary:'A4 descrive la criticità; non indica auto-miglioramento. La categoria appropriata dipende dall’uso. Questi livelli appartengono al riferimento VOCE e non costituiscono una certificazione europea.',actions:[['Esamina i controlli','agent-conformance'],['Leggi il riferimento A0–A4 completo','agent-infrastructure#maturity']]}
    },
    conformance:{type:'flow',proof:true,
      en:{title:'How do you examine an agent’s controls?',intro:'Agent Conformance connects a system’s architecture to 48 controls. Each control has its own evidence state; one overall score would conceal important gaps.',stages:[
        ['Describe the system','Identify agents, tools, data, permissions and the intended use.'],
        ['Choose the scope','Select the A0–A4 category and the relevant control domains.'],
        ['Examine the evidence','Distinguish assertions, documents, recorded tests and operational evidence.'],
        ['Identify the gaps','Review missing evidence and critical authority gaps before deciding what to change.']
      ],boundary:'The browser-local self-assessment records an evidence state. It does not execute the tests or issue certification. A critical gap must remain visible even when other controls are well supported.',actions:[['Open the self-assessment','agent-conformance#conformance-app'],['Understand the architecture','agent-infrastructure']]},
      fr:{title:'Comment examiner les contrôles d’un agent?',intro:'Agent Conformance relie l’architecture d’un système à 48 contrôles. Chaque contrôle possède son état de preuve; un score global masquerait des lacunes importantes.',stages:[
        ['Décrire le système','Identifier les agents, outils, données, permissions et l’usage prévu.'],
        ['Définir le périmètre','Choisir la catégorie A0–A4 et les domaines de contrôle concernés.'],
        ['Examiner les preuves','Distinguer les déclarations, documents, tests consignés et preuves en fonctionnement.'],
        ['Repérer les lacunes','Examiner les preuves manquantes et les défauts critiques d’autorité avant de décider des corrections.']
      ],boundary:'L’auto-évaluation locale dans le navigateur consigne un état de preuve. Elle n’exécute pas les tests et ne délivre pas de certification. Une lacune critique doit rester visible même si d’autres contrôles sont bien étayés.',actions:[['Ouvrir l’auto-évaluation','agent-conformance#conformance-app'],['Comprendre l’architecture','agent-infrastructure']]},
      it:{title:'Come esaminare i controlli di un agente?',intro:'Agent Conformance collega l’architettura di un sistema a 48 controlli. Ogni controllo ha il proprio stato di evidenza; un punteggio complessivo nasconderebbe lacune importanti.',stages:[
        ['Descrivere il sistema','Identificare agenti, strumenti, dati, permessi e uso previsto.'],
        ['Definire il perimetro','Scegliere la categoria A0–A4 e gli ambiti di controllo pertinenti.'],
        ['Esaminare le evidenze','Distinguere dichiarazioni, documenti, test registrati ed evidenze in esercizio.'],
        ['Individuare le lacune','Esaminare le evidenze mancanti e le lacune critiche di autorità prima di decidere le correzioni.']
      ],boundary:'L’autovalutazione locale nel browser registra uno stato di evidenza. Non esegue i test e non rilascia certificazioni. Una lacuna critica deve restare visibile anche quando altri controlli sono ben documentati.',actions:[['Apri l’autovalutazione','agent-conformance#conformance-app'],['Comprendi l’architettura','agent-infrastructure']]}
    },
    argos:{type:'flow',
      en:{title:'What changes after the system changes?',intro:'ARGOS structures a new assurance cycle when a material change makes the previous conclusion insufficient. The cycle covers the system and the conditions of human oversight.',stages:[
        ['Baseline','Record the versions, permissions and configuration being assessed.'],['Observe','Examine actual tasks, errors, costs and human interventions.'],['Detect change','Identify a material change, drift, incident or supplier event.'],['Re-evaluate','Repeat the relevant task, security, authority and cognitive-control evaluations.'],['Compare','Compare the new results with the accepted baseline.'],['Decide','Continue within conditions, restrict, roll back or withdraw the capability.'],['Retain evidence','Keep the dated results, decision and accountable owner.'],['Re-open','Start another cycle at the next material change.']
      ],boundary:'The cycle is a framework to implement. Monitoring, triggers and accountable decision-makers must be configured for the assessed system; this diagram does not run them.',actions:[['Read the complete assurance cycle','argos#assurance-cycle'],['Review the control evidence','agent-conformance']]},
      fr:{title:'Que réexaminer quand le système change?',intro:'ARGOS structure un nouveau cycle d’assurance lorsqu’un changement matériel rend la conclusion précédente insuffisante. Le cycle couvre le système et les conditions de supervision humaine.',stages:[
        ['Référence initiale','Consigner les versions, permissions et configurations examinées.'],['Observer','Examiner les tâches réelles, erreurs, coûts et interventions humaines.'],['Détecter le changement','Identifier une modification matérielle, dérive, incident ou événement fournisseur.'],['Réévaluer','Répéter les évaluations pertinentes de tâches, sécurité, autorité et contrôles cognitifs.'],['Comparer','Comparer les nouveaux résultats à la référence acceptée.'],['Décider','Maintenir sous conditions, restreindre, revenir en arrière ou retirer la capacité.'],['Conserver les preuves','Garder les résultats datés, la décision et le responsable identifié.'],['Rouvrir','Reprendre le cycle au prochain changement matériel.']
      ],boundary:'Ce cycle est un cadre à mettre en œuvre. Surveillance, déclencheurs et responsables de décision doivent être configurés pour le système évalué; le schéma ne les exécute pas.',actions:[['Lire le cycle d’assurance complet','argos#assurance-cycle'],['Examiner les preuves de contrôle','agent-conformance']]},
      it:{title:'Che cosa riesaminare quando il sistema cambia?',intro:'ARGOS struttura un nuovo ciclo di assurance quando una modifica sostanziale rende insufficiente la conclusione precedente. Il ciclo riguarda il sistema e le condizioni della supervisione umana.',stages:[
        ['Riferimento iniziale','Registrare versioni, permessi e configurazioni esaminati.'],['Osservare','Esaminare le attività reali, gli errori, i costi e gli interventi umani.'],['Rilevare il cambiamento','Identificare una modifica sostanziale, un drift, un incidente o un evento del fornitore.'],['Rivalutare','Ripetere le valutazioni pertinenti su attività, sicurezza, autorità e controlli cognitivi.'],['Confrontare','Confrontare i nuovi risultati con il riferimento accettato.'],['Decidere','Proseguire a condizioni definite, limitare, ripristinare o ritirare la capacità.'],['Conservare le evidenze','Conservare i risultati datati, la decisione e il responsabile identificato.'],['Riaprire','Riprendere il ciclo alla successiva modifica sostanziale.']
      ],boundary:'Questo ciclo è un quadro da implementare. Monitoraggio, trigger e responsabili delle decisioni devono essere configurati per il sistema valutato; lo schema non li esegue.',actions:[['Leggi il ciclo di assurance completo','argos#assurance-cycle'],['Esamina le evidenze di controllo','agent-conformance']]}
    },
    cognitive:{type:'flow',
      en:{title:'Can the human reviewer still take control?',intro:'Human Cognitive Assurance examines oversight through 24 controls. Approval is meaningful only when the reviewer has the information, attention and practical ability to intervene.',stages:[
        ['Describe the workflow','Identify the decisions, workload, interface and people involved.'],['Find relevant evidence','The VOCE Cognitive Agent searches the corpus and points to controls to examine.'],['Examine oversight','Test understanding, verification quality, alert burden and intervention conditions.'],['Adjust the workflow','Set limits, escalation and supervision arrangements, then document what works in operation.']
      ],boundary:'This is system and workflow analysis, not an individual psychological or neuropsychological diagnosis. A corpus-based recommendation is not proof that a human control works.',actions:[['Describe a workflow to the Cognitive Agent','human-cognitive-assurance#cognitive-agent'],['See the technical control framework','agent-conformance']]},
      fr:{title:'Le superviseur peut-il encore reprendre la main?',intro:'Human Cognitive Assurance examine la supervision à travers 24 contrôles. Une validation suppose que la personne dispose de l’information, de l’attention et des moyens réels d’intervenir.',stages:[
        ['Décrire le workflow','Identifier les décisions, la charge de travail, l’interface et les personnes concernées.'],['Trouver les éléments pertinents','Le VOCE Cognitive Agent recherche dans le corpus et indique les contrôles à examiner.'],['Examiner la supervision','Tester la compréhension, la qualité de vérification, la charge d’alertes et les conditions d’intervention.'],['Adapter le workflow','Définir les limites, l’escalade et les modalités de supervision, puis documenter ce qui fonctionne réellement.']
      ],boundary:'L’analyse concerne les systèmes et les workflows, sans diagnostic psychologique ou neuropsychologique individuel. Une recommandation fondée sur le corpus ne prouve pas qu’un contrôle humain fonctionne.',actions:[['Décrire un workflow au Cognitive Agent','human-cognitive-assurance#cognitive-agent'],['Voir le cadre des contrôles techniques','agent-conformance']]},
      it:{title:'Il supervisore può ancora riprendere il controllo?',intro:'Human Cognitive Assurance esamina la supervisione attraverso 24 controlli. Un’approvazione richiede che la persona disponga delle informazioni, dell’attenzione e dei mezzi effettivi per intervenire.',stages:[
        ['Descrivere il workflow','Identificare decisioni, carico di lavoro, interfaccia e persone coinvolte.'],['Trovare gli elementi pertinenti','Il VOCE Cognitive Agent cerca nel corpus e indica i controlli da esaminare.'],['Esaminare la supervisione','Testare comprensione, qualità della verifica, carico degli avvisi e condizioni d’intervento.'],['Adattare il workflow','Definire limiti, escalation e modalità di supervisione, poi documentare ciò che funziona in esercizio.']
      ],boundary:'L’analisi riguarda sistemi e workflow, senza diagnosi psicologiche o neuropsicologiche individuali. Una raccomandazione fondata sul corpus non dimostra che un controllo umano funzioni.',actions:[['Descrivi un workflow al Cognitive Agent','human-cognitive-assurance#cognitive-agent'],['Vedi il quadro dei controlli tecnici','agent-conformance']]}
    },
    guide:{type:'flow',
      en:{title:'How does the VOCE Guide help you find an answer?',intro:'The Guide searches the VOCE corpus from a question in your own words. Its answer points to supporting documents and relevant pathways in the site.',stages:[
        ['Ask a question','Describe the subject or the problem you want to examine.'],['Search the corpus','The Guide finds relevant VOCE documents.'],['Read with references','The answer links to the documents and suggested pathways.'],['Check the support','Open the documents, review their scope and decide whether they answer your question.']
      ],boundary:'When the corpus cannot support an answer sufficiently, the Guide should say so. A suggested pathway helps navigation; it does not establish that every claim is proven.',actions:[['Ask the Guide','#home-guide-query'],['Browse the Academy','archive']]},
      fr:{title:'Comment le Guide VOCE vous aide-t-il à trouver une réponse?',intro:'Le Guide recherche dans le corpus VOCE à partir d’une question formulée avec vos mots. Sa réponse renvoie aux documents qui la soutiennent et aux parcours pertinents du site.',stages:[
        ['Poser une question','Décrire le sujet ou le problème que vous souhaitez examiner.'],['Rechercher dans le corpus','Le Guide retrouve les documents VOCE pertinents.'],['Lire avec les références','La réponse donne accès aux documents et aux parcours proposés.'],['Vérifier les éléments','Ouvrir les documents, examiner leur périmètre et décider s’ils répondent à votre question.']
      ],boundary:'Lorsque le corpus ne permet pas d’étayer suffisamment une réponse, le Guide doit le signaler. Un parcours proposé facilite la navigation; il ne démontre pas que chaque affirmation est prouvée.',actions:[['Interroger le Guide','#home-guide-query'],['Parcourir l’Academy','archive']]},
      it:{title:'Come ti aiuta la Guida VOCE a trovare una risposta?',intro:'La Guida cerca nel corpus VOCE a partire da una domanda formulata con parole tue. La risposta rimanda ai documenti che la sostengono e ai percorsi pertinenti del sito.',stages:[
        ['Porre una domanda','Descrivere l’argomento o il problema da esaminare.'],['Cercare nel corpus','La Guida trova i documenti VOCE pertinenti.'],['Leggere con i riferimenti','La risposta rimanda ai documenti e ai percorsi suggeriti.'],['Verificare gli elementi','Aprire i documenti, esaminarne il perimetro e decidere se rispondono alla domanda.']
      ],boundary:'Quando il corpus non sostiene sufficientemente una risposta, la Guida deve segnalarlo. Un percorso suggerito facilita la navigazione; non dimostra che ogni affermazione sia provata.',actions:[['Interroga la Guida','#home-guide-query'],['Esplora l’Academy','archive']]}
    }
  };
  Object.assign(GUIDES, {
    overview:{type:'map',
      en:{title:'How do the VOCE tools work together?',intro:'Each tool answers a different question. Documents and evidence connect the analysis of an architecture to its controls and later reassessment.',stages:[['Corpus','Find the publications and sources relevant to the question.'],['Atlas','Explore documented relationships and return to the supporting texts.'],['Agent Infrastructure','Describe the system, its dependencies and its scope of action.'],['Agent Conformance','Examine the applicable controls and their evidence states.'],['Human Cognitive Assurance','Examine whether people can understand, verify and intervene.'],['ARGOS','Reopen the assessment after a material change and record the decision.']],boundary:'These tools support an examination. A documented relationship, a recommendation and an operational test provide different kinds of support.',actions:[['Explore the governance framework','governance'],['Explore Atlas','atlas']]},
      fr:{title:'Comment les outils VOCE s’articulent-ils?',intro:'Chaque outil répond à une question différente. Les documents et les preuves relient l’analyse d’une architecture à ses contrôles et à sa réévaluation.',stages:[['Corpus','Retrouver les publications et sources pertinentes pour la question.'],['Atlas','Explorer les relations documentées et revenir aux textes qui les étayent.'],['Agent Infrastructure','Décrire le système, ses dépendances et son périmètre d’action.'],['Agent Conformance','Examiner les contrôles applicables et leurs états de preuve.'],['Human Cognitive Assurance','Examiner si les personnes peuvent comprendre, vérifier et intervenir.'],['ARGOS','Rouvrir l’évaluation après un changement matériel et consigner la décision.']],boundary:'Ces outils soutiennent un examen. Une relation documentée, une recommandation et un test en fonctionnement apportent des éléments de nature différente.',actions:[['Explorer le cadre de gouvernance','governance'],['Explorer Atlas','atlas']]},
      it:{title:'Come si collegano gli strumenti VOCE?',intro:'Ogni strumento risponde a una domanda diversa. Documenti ed evidenze collegano l’analisi di un’architettura ai suoi controlli e alla successiva rivalutazione.',stages:[['Corpus','Trovare le pubblicazioni e le fonti pertinenti alla domanda.'],['Atlas','Esplorare le relazioni documentate e tornare ai testi che le sostengono.'],['Agent Infrastructure','Descrivere il sistema, le sue dipendenze e il perimetro d’azione.'],['Agent Conformance','Esaminare i controlli applicabili e i loro stati di evidenza.'],['Human Cognitive Assurance','Esaminare se le persone possono comprendere, verificare e intervenire.'],['ARGOS','Riaprire la valutazione dopo una modifica sostanziale e registrare la decisione.']],boundary:'Questi strumenti sostengono un esame. Una relazione documentata, una raccomandazione e un test in esercizio forniscono elementi di natura diversa.',actions:[['Esplora il quadro di governance','governance'],['Esplora Atlas','atlas']]}
    },
    atlas:{type:'flow',
      en:{title:'What does a line in Atlas mean?',intro:'Atlas makes a documented relationship visible. Its value comes from the type of relationship and the source that supports it.',stages:[['Choose a concept','Start with the subject you want to understand.'],['Examine the relationship','Read its type: mechanism, dependency, tension or another documented relation.'],['Open the source','Return to the publication or research record behind the connection.'],['Check the limits','Distinguish what the source establishes from an interpretation or hypothesis.']],boundary:'Two concepts appearing together is insufficient. A displayed link does not by itself establish a causal relationship.',actions:[['Open the map','atlas'],['Read the evidence standard','standards']]},
      fr:{title:'Que signifie une ligne dans Atlas?',intro:'Atlas rend une relation documentée visible. Sa valeur tient au type de relation et à la source qui la soutient.',stages:[['Choisir un concept','Partir du sujet que vous souhaitez comprendre.'],['Examiner la relation','Lire sa nature: mécanisme, dépendance, tension ou autre relation documentée.'],['Ouvrir la source','Revenir à la publication ou au travail de recherche qui étaye le lien.'],['Vérifier les limites','Distinguer ce que la source établit d’une interprétation ou d’une hypothèse.']],boundary:'La présence de deux concepts dans un même texte ne suffit pas. Un lien affiché ne démontre pas à lui seul une relation causale.',actions:[['Ouvrir la carte','atlas'],['Lire le standard de preuve','standards']]},
      it:{title:'Che cosa significa una linea in Atlas?',intro:'Atlas rende visibile una relazione documentata. Il suo valore dipende dal tipo di relazione e dalla fonte che la sostiene.',stages:[['Scegliere un concetto','Partire dall’argomento che si vuole comprendere.'],['Esaminare la relazione','Leggerne la natura: meccanismo, dipendenza, tensione o altra relazione documentata.'],['Aprire la fonte','Tornare alla pubblicazione o alla ricerca che sostiene il collegamento.'],['Verificare i limiti','Distinguere ciò che la fonte dimostra da un’interpretazione o un’ipotesi.']],boundary:'La presenza di due concetti nello stesso testo non basta. Un collegamento visualizzato non dimostra da solo una relazione causale.',actions:[['Apri la mappa','atlas'],['Leggi lo standard delle evidenze','standards']]}
    },
    'academy-research':{type:'map',
      en:{title:'Where should you look for a VOCE publication?',intro:'Academy helps readers learn and navigate the corpus. Research identifies the nature of the work and the method behind it.',stages:[['Academy','Full texts, courses, sources and pathways for understanding a subject.'],['Formal research','A research question, method and results to examine on their own terms.'],['Applied research','An examination of a practical problem, system or workflow.'],['Editorial intelligence','An analysis of signals and sources, with interpretations and limits made visible.']],boundary:'An Academy article is not automatically formal research. Read the publication’s stated category and method before using it as evidence.',actions:[['Browse the Academy','archive'],['Explore Research','research']]},
      fr:{title:'Où chercher une publication VOCE?',intro:'L’Academy aide à apprendre et à parcourir le corpus. Research précise la nature du travail et la méthode qui le soutient.',stages:[['Academy','Textes complets, cours, sources et parcours pour comprendre un sujet.'],['Recherche formelle','Une question de recherche, une méthode et des résultats à examiner selon leur périmètre.'],['Recherche appliquée','L’examen d’un problème concret, d’un système ou d’un workflow.'],['Intelligence éditoriale','Une analyse des signaux et des sources, avec les interprétations et les limites visibles.']],boundary:'Un article de l’Academy n’est pas automatiquement un travail de recherche formelle. Lire sa catégorie et sa méthode avant de l’utiliser comme preuve.',actions:[['Parcourir l’Academy','archive'],['Explorer Research','research']]},
      it:{title:'Dove cercare una pubblicazione VOCE?',intro:'Academy aiuta a imparare e a esplorare il corpus. Research chiarisce la natura del lavoro e il metodo che lo sostiene.',stages:[['Academy','Testi completi, corsi, fonti e percorsi per comprendere un argomento.'],['Ricerca formale','Una domanda di ricerca, un metodo e risultati da esaminare nel loro perimetro.'],['Ricerca applicata','L’esame di un problema concreto, di un sistema o di un workflow.'],['Intelligence editoriale','Un’analisi di segnali e fonti, con interpretazioni e limiti visibili.']],boundary:'Un articolo di Academy non è automaticamente ricerca formale. Leggerne la categoria e il metodo prima di usarlo come evidenza.',actions:[['Esplora Academy','archive'],['Esplora Research','research']]}
    },
    sovereignty:{type:'flow',
      en:{title:'Can you replace a supplier without losing control?',intro:'Operational sovereignty depends on the ability to govern dependencies and test an exit. A model’s origin or an open licence is only part of the examination.',stages:[['Map dependencies','Identify compute, models, data, identity, tools and contracts.'],['Locate control','Determine who can access data, change a component or revoke a permission.'],['Prepare portability','Keep exportable data, reusable evaluations and documented interfaces.'],['Test the exit','Disconnect or replace a component and check what still works.']],boundary:'Open weights, source code and hosting are different questions. Check the actual licence, deployment conditions and replacement costs.',actions:[['Examine technological sovereignty','sovereignty'],['Examine agent infrastructure','agent-infrastructure']]},
      fr:{title:'Pouvez-vous remplacer un fournisseur sans perdre le contrôle?',intro:'La souveraineté opérationnelle dépend de la capacité à gouverner les dépendances et à tester une sortie. L’origine d’un modèle ou une licence ouverte ne couvre qu’une partie de l’examen.',stages:[['Cartographier les dépendances','Identifier le calcul, les modèles, données, identités, outils et contrats.'],['Situer le contrôle','Déterminer qui peut accéder aux données, modifier un composant ou révoquer un droit.'],['Préparer la portabilité','Conserver des données exportables, des évaluations réutilisables et des interfaces documentées.'],['Tester la sortie','Déconnecter ou remplacer un composant et vérifier ce qui fonctionne encore.']],boundary:'Poids ouverts, code source et hébergement sont des questions distinctes. Vérifier la licence réelle, les conditions de déploiement et les coûts de remplacement.',actions:[['Examiner la souveraineté technologique','sovereignty'],['Examiner l’infrastructure des agents','agent-infrastructure']]},
      it:{title:'Puoi sostituire un fornitore senza perdere il controllo?',intro:'La sovranità operativa dipende dalla capacità di governare le dipendenze e testare un’uscita. L’origine di un modello o una licenza aperta copre solo una parte dell’esame.',stages:[['Mappare le dipendenze','Identificare calcolo, modelli, dati, identità, strumenti e contratti.'],['Individuare il controllo','Stabilire chi può accedere ai dati, modificare un componente o revocare un permesso.'],['Preparare la portabilità','Conservare dati esportabili, valutazioni riutilizzabili e interfacce documentate.'],['Testare l’uscita','Scollegare o sostituire un componente e verificare che cosa funziona ancora.']],boundary:'Pesi aperti, codice sorgente e hosting sono questioni distinte. Verificare la licenza effettiva, le condizioni di distribuzione e i costi di sostituzione.',actions:[['Esamina la sovranità tecnologica','sovereignty'],['Esamina l’infrastruttura degli agenti','agent-infrastructure']]}
    },
    'light-workforce':{type:'flow',
      en:{title:'If junior tasks disappear, how do future experts learn?',intro:'Automating execution also changes the tasks through which people learn. Workforce design needs an explicit apprenticeship pathway.',stages:[['Map the tasks','Identify what is automated and what previously developed practical judgment.'],['Retain learning situations','Plan supervised practice, simulation and review of real exceptions.'],['Define responsibility','Assign supervision, escalation and decisions to identified people.'],['Measure progression','Track competence, rework, outcomes and intervention needs alongside costs.']],boundary:'Removing a routine task does not automatically remove a role or produce expertise. The effects depend on the work and the training arrangements.',actions:[['Explore light workforce','light-workforce'],['Examine human oversight','human-cognitive-assurance']]},
      fr:{title:'Si les tâches juniors disparaissent, comment former les futurs experts?',intro:'Automatiser l’exécution modifie aussi les tâches par lesquelles les personnes apprennent. L’organisation du travail doit prévoir un parcours d’apprentissage explicite.',stages:[['Cartographier les tâches','Identifier ce qui est automatisé et ce qui développait le jugement pratique.'],['Conserver des situations d’apprentissage','Prévoir la pratique supervisée, la simulation et l’examen d’exceptions réelles.'],['Définir les responsabilités','Attribuer la supervision, l’escalade et les décisions à des personnes identifiées.'],['Mesurer la progression','Suivre la compétence, les reprises, les résultats et les besoins d’intervention avec les coûts.']],boundary:'Supprimer une tâche répétitive ne supprime pas automatiquement un métier et ne produit pas l’expertise. Les effets dépendent du travail et de l’organisation de la formation.',actions:[['Explorer light workforce','light-workforce'],['Examiner la supervision humaine','human-cognitive-assurance']]},
      it:{title:'Se scompaiono le attività junior, come si formano i futuri esperti?',intro:'Automatizzare l’esecuzione cambia anche le attività attraverso cui le persone imparano. L’organizzazione del lavoro deve prevedere un percorso di apprendimento esplicito.',stages:[['Mappare le attività','Identificare ciò che viene automatizzato e ciò che sviluppava il giudizio pratico.'],['Conservare occasioni di apprendimento','Prevedere pratica supervisionata, simulazione ed esame di eccezioni reali.'],['Definire le responsabilità','Assegnare supervisione, escalation e decisioni a persone identificate.'],['Misurare i progressi','Seguire competenze, rilavorazioni, risultati e necessità d’intervento insieme ai costi.']],boundary:'Eliminare un’attività ripetitiva non elimina automaticamente un ruolo e non produce competenza. Gli effetti dipendono dal lavoro e dall’organizzazione della formazione.',actions:[['Esplora light workforce','light-workforce'],['Esamina la supervisione umana','human-cognitive-assurance']]}
    },
    technoference:{type:'flow',
      en:{title:'What happens when a notification interrupts an interaction?',intro:'Technoference examines how connected devices enter an ongoing exchange. The interruption and the return to the interaction matter alongside total screen time.',stages:[['Ongoing exchange','Observe attention, timing, gestures and turn-taking.'],['Interruption','A glance, alert or response redirects attention to the device.'],['Return','Examine how the person resumes the exchange and what was missed.'],['Study the pattern','Compare interruptions, context and interaction quality without assuming causality.']],boundary:'This diagram describes a mechanism to examine, not an individual diagnosis. Association, a proposed mechanism and causal evidence must remain distinct.',actions:[['Read the technoference research pathway','technoference'],['Explore Research','research']]},
      fr:{title:'Que se passe-t-il quand une notification interrompt un échange?',intro:'La technoference examine comment les appareils connectés entrent dans une interaction en cours. L’interruption et le retour à l’échange comptent autant que la durée totale d’écran.',stages:[['Échange en cours','Observer l’attention, le rythme, les gestes et les tours de parole.'],['Interruption','Un regard, une alerte ou une réponse déplace l’attention vers l’appareil.'],['Retour','Examiner comment la personne reprend l’échange et ce qui a été manqué.'],['Étudier la répétition','Comparer les interruptions, le contexte et la qualité d’interaction sans supposer un lien causal.']],boundary:'Ce schéma décrit un mécanisme à examiner, sans diagnostic individuel. Association, mécanisme proposé et preuve causale doivent rester distincts.',actions:[['Lire le parcours de recherche technoference','technoference'],['Explorer Research','research']]},
      it:{title:'Che cosa accade quando una notifica interrompe uno scambio?',intro:'La technoference esamina come i dispositivi connessi entrano in un’interazione in corso. L’interruzione e il ritorno allo scambio contano insieme al tempo totale davanti allo schermo.',stages:[['Scambio in corso','Osservare attenzione, ritmo, gesti e alternanza dei turni.'],['Interruzione','Uno sguardo, un avviso o una risposta sposta l’attenzione sul dispositivo.'],['Ritorno','Esaminare come la persona riprende lo scambio e che cosa è stato perso.'],['Studiare la ripetizione','Confrontare interruzioni, contesto e qualità dell’interazione senza presumere causalità.']],boundary:'Questo schema descrive un meccanismo da esaminare, senza diagnosi individuali. Associazione, meccanismo proposto ed evidenza causale devono restare distinti.',actions:[['Leggi il percorso di ricerca sulla technoference','technoference'],['Esplora Research','research']]}
    },
    art:{type:'flow',
      en:{title:'How can you reconstruct an artwork’s documented history?',intro:'A provenance dossier makes the chain of information inspectable. Different documents answer different questions about a work.',stages:[['Gather the documents','Collect dated records of ownership, exhibitions, publications and transfers.'],['Reconstruct the sequence','Place the documents in time and identify their origin.'],['Expose the gaps','Keep uncertain attribution, missing periods and conflicting records visible.'],['Seek specialist verification','Refer questions of authenticity, condition, title and export status to the relevant specialists.']],boundary:'A documented provenance does not by itself certify authenticity or establish every legal question. VOCE organises the dossier and does not issue authenticity certificates.',actions:[['Explore VOCE Art','art'],['Read the evidence method','standards']]},
      fr:{title:'Comment reconstituer le parcours documenté d’une œuvre?',intro:'Un dossier de provenance rend la chaîne d’information examinable. Des documents différents répondent à des questions différentes sur l’œuvre.',stages:[['Réunir les documents','Collecter les traces datées de propriété, expositions, publications et transferts.'],['Reconstituer la séquence','Situer les documents dans le temps et identifier leur origine.'],['Rendre les lacunes visibles','Conserver les attributions incertaines, périodes manquantes et documents contradictoires.'],['Solliciter les vérifications spécialisées','Confier les questions d’authenticité, état, propriété et export aux spécialistes concernés.']],boundary:'Une provenance documentée ne certifie pas à elle seule l’authenticité et ne règle pas toutes les questions juridiques. VOCE organise le dossier et ne délivre pas de certificat d’authenticité.',actions:[['Explorer VOCE Art','art'],['Lire la méthode de preuve','standards']]},
      it:{title:'Come ricostruire la storia documentata di un’opera?',intro:'Un dossier di provenienza rende esaminabile la catena delle informazioni. Documenti diversi rispondono a domande diverse sull’opera.',stages:[['Raccogliere i documenti','Riunire le tracce datate di proprietà, mostre, pubblicazioni e trasferimenti.'],['Ricostruire la sequenza','Collocare i documenti nel tempo e identificarne l’origine.'],['Rendere visibili le lacune','Conservare attribuzioni incerte, periodi mancanti e documenti contraddittori.'],['Richiedere verifiche specialistiche','Affidare autenticità, stato, proprietà ed esportazione agli specialisti competenti.']],boundary:'Una provenienza documentata non certifica da sola l’autenticità e non risolve ogni questione giuridica. VOCE organizza il dossier e non rilascia certificati di autenticità.',actions:[['Esplora VOCE Art','art'],['Leggi il metodo delle evidenze','standards']]}
    },
    method:{type:'flow',
      en:{title:'How does VOCE move from a source to a recommendation?',intro:'A useful analysis makes its sources, interpretation and uncertainty inspectable. The recommendation must remain connected to that record.',stages:[['Verify the source','Identify its origin, date, scope and whether it is primary evidence.'],['Separate the claims','Distinguish facts, interpretations, scenarios and supplier assertions.'],['Examine the consequences','Connect dependencies, permissions, economics and human responsibility.'],['State the recommendation','Explain its support, uncertainty and the changes that would require revision.']],boundary:'Missing information remains missing. A recommendation’s confidence must reflect the strength and currency of its evidence.',actions:[['Read the VOCE standards','standards'],['Discover the institution','about']]},
      fr:{title:'Comment VOCE passe-t-il d’une source à une recommandation?',intro:'Une analyse utile rend ses sources, son interprétation et ses incertitudes examinables. La recommandation doit rester reliée à ce dossier.',stages:[['Vérifier la source','Identifier son origine, sa date, son périmètre et sa nature primaire ou secondaire.'],['Distinguer les affirmations','Séparer les faits, interprétations, scénarios et déclarations fournisseurs.'],['Examiner les conséquences','Relier les dépendances, permissions, coûts et responsabilités humaines.'],['Formuler la recommandation','Expliquer son appui, ses incertitudes et les changements qui imposeraient sa révision.']],boundary:'Une information manquante reste manquante. Le degré de confiance d’une recommandation doit refléter la solidité et l’actualité de ses preuves.',actions:[['Lire les standards VOCE','standards'],['Découvrir l’institution','about']]},
      it:{title:'Come passa VOCE da una fonte a una raccomandazione?',intro:'Un’analisi utile rende esaminabili le fonti, l’interpretazione e le incertezze. La raccomandazione deve restare collegata a quel dossier.',stages:[['Verificare la fonte','Identificarne origine, data, perimetro e natura primaria o secondaria.'],['Distinguere le affermazioni','Separare fatti, interpretazioni, scenari e dichiarazioni dei fornitori.'],['Esaminare le conseguenze','Collegare dipendenze, permessi, costi e responsabilità umane.'],['Formulare la raccomandazione','Spiegarne il supporto, le incertezze e i cambiamenti che ne richiederebbero la revisione.']],boundary:'Un’informazione mancante resta mancante. Il livello di fiducia deve riflettere la solidità e l’attualità delle evidenze.',actions:[['Leggi gli standard VOCE','standards'],['Scopri l’istituzione','about']]}
    },
    connections:{type:'map',
      en:{title:'API, MCP, A2A: how does an agent connect?',intro:'These interfaces cover different relationships. The connection must be examined together with identity and the actions actually authorised.',stages:[['API','A defined interface for requesting a service or accessing data.'],['MCP','A protocol through which an AI application can discover and use a server’s tools, resources or prompts.'],['A2A','A protocol for exchanges and task collaboration between agent systems.'],['Identity and permissions','Determine who is making the request, what it can do and how access is revoked.']],boundary:'A protocol connection does not by itself authorise a business action. Authentication, data scopes and approval rules remain part of the architecture.',actions:[['Read the architecture reference','agent-infrastructure'],['Explore AI governance','governance']]},
      fr:{title:'API, MCP, A2A: comment un agent se connecte-t-il?',intro:'Ces interfaces couvrent des relations différentes. La connexion s’examine avec l’identité et les actions réellement autorisées.',stages:[['API','Une interface définie pour demander un service ou accéder à des données.'],['MCP','Un protocole permettant à une application IA de découvrir et utiliser les outils, ressources ou prompts d’un serveur.'],['A2A','Un protocole d’échange et de collaboration sur des tâches entre systèmes d’agents.'],['Identité et permissions','Déterminer qui fait la demande, ce qu’il peut faire et comment révoquer l’accès.']],boundary:'Une connexion par protocole n’autorise pas à elle seule une action métier. Authentification, périmètres de données et règles de validation restent dans l’architecture.',actions:[['Lire le référentiel d’architecture','agent-infrastructure'],['Explorer la gouvernance IA','governance']]},
      it:{title:'API, MCP, A2A: come si connette un agente?',intro:'Queste interfacce riguardano relazioni diverse. La connessione va esaminata insieme all’identità e alle azioni effettivamente autorizzate.',stages:[['API','Un’interfaccia definita per richiedere un servizio o accedere ai dati.'],['MCP','Un protocollo che permette a un’applicazione IA di scoprire e usare strumenti, risorse o prompt di un server.'],['A2A','Un protocollo per scambi e collaborazione su attività tra sistemi di agenti.'],['Identità e permessi','Stabilire chi fa la richiesta, che cosa può fare e come revocare l’accesso.']],boundary:'Una connessione tramite protocollo non autorizza da sola un’azione operativa. Autenticazione, perimetri dei dati e regole di approvazione restano parte dell’architettura.',actions:[['Leggi il riferimento di architettura','agent-infrastructure'],['Esplora la governance IA','governance']]}
    },
    permissions:{type:'map',
      en:{title:'An agent can read a file. Can it also change it or pay?',intro:'Authority must be assigned action by action. Access to a document does not establish permission for a transaction.',stages:[['Read','Define which data the agent can access and for what purpose.'],['Change','Specify the records it may edit and the conditions for recovery.'],['Pay or commit','Set transaction limits, required approvals and separation of duties.'],['Stop or revoke','Ensure an identified person can suspend execution and remove access.']],boundary:'Reading, editing and making a commitment are separate permissions. Check the effective configuration and test whether restrictions can be bypassed.',actions:[['Examine the authority controls','agent-conformance'],['Read the operating standards','standards']]},
      fr:{title:'Un agent peut lire un dossier. Peut-il aussi le modifier ou payer?',intro:'L’autorité doit être attribuée action par action. L’accès à un document n’établit pas le droit d’effectuer une transaction.',stages:[['Lire','Définir les données accessibles et la finalité de l’accès.'],['Modifier','Préciser les éléments modifiables et les conditions de retour arrière.'],['Payer ou engager','Fixer les limites transactionnelles, validations requises et séparations des fonctions.'],['Arrêter ou révoquer','Permettre à une personne identifiée de suspendre l’exécution et retirer les accès.']],boundary:'Lire, modifier et prendre un engagement sont des permissions distinctes. Vérifier la configuration effective et tester si les restrictions peuvent être contournées.',actions:[['Examiner les contrôles d’autorité','agent-conformance'],['Lire les standards d’exploitation','standards']]},
      it:{title:'Un agente può leggere un dossier. Può anche modificarlo o pagare?',intro:'L’autorità va assegnata azione per azione. L’accesso a un documento non stabilisce il diritto di effettuare una transazione.',stages:[['Leggere','Definire i dati accessibili e la finalità dell’accesso.'],['Modificare','Precisare gli elementi modificabili e le condizioni di ripristino.'],['Pagare o impegnare','Stabilire limiti di transazione, approvazioni richieste e separazione dei compiti.'],['Fermare o revocare','Permettere a una persona identificata di sospendere l’esecuzione e rimuovere gli accessi.']],boundary:'Leggere, modificare e assumere un impegno sono permessi distinti. Verificare la configurazione effettiva e testare se le restrizioni possono essere aggirate.',actions:[['Esamina i controlli di autorità','agent-conformance'],['Leggi gli standard operativi','standards']]}
    },
    costs:{type:'flow',
      en:{title:'A task succeeds after twenty attempts. What did it really cost?',intro:'The useful unit is an accepted completed task. Model usage is only one part of the cost of delivering that outcome.',stages:[['Count all attempts','Include failed calls, retries, tool usage and infrastructure.'],['Include human work','Measure review, escalation, correction and operational support.'],['Check the outcome','Separate an output produced from a result accepted at the required quality.'],['Compare complete costs','Divide the period’s total cost by accepted completed tasks, with the same scope.']],boundary:'The result depends on what is included, the observation period and the acceptance criteria. It does not by itself establish a return on investment.',actions:[['Read the governance and economics framework','governance'],['Examine operational changes with ARGOS','argos']]},
      fr:{title:'Une tâche réussit après vingt tentatives. Quel est son coût réel?',intro:'L’unité utile est la tâche terminée et acceptée. L’usage du modèle ne représente qu’une partie du coût nécessaire pour obtenir ce résultat.',stages:[['Compter toutes les tentatives','Inclure les appels échoués, reprises, outils et infrastructure.'],['Inclure le travail humain','Mesurer la vérification, l’escalade, les corrections et le support d’exploitation.'],['Vérifier le résultat','Distinguer une sortie produite d’un résultat accepté au niveau de qualité requis.'],['Comparer les coûts complets','Diviser le coût total de la période par les tâches terminées et acceptées, à périmètre identique.']],boundary:'Le résultat dépend des coûts inclus, de la période observée et des critères d’acceptation. Il ne démontre pas à lui seul un retour sur investissement.',actions:[['Lire le cadre de gouvernance et d’économie','governance'],['Examiner les changements avec ARGOS','argos']]},
      it:{title:'Un’attività riesce dopo venti tentativi. Qual è il suo costo reale?',intro:'L’unità utile è l’attività completata e accettata. L’uso del modello è solo una parte del costo necessario per ottenere quel risultato.',stages:[['Contare tutti i tentativi','Includere chiamate fallite, nuovi tentativi, strumenti e infrastruttura.'],['Includere il lavoro umano','Misurare verifica, escalation, correzioni e supporto operativo.'],['Verificare il risultato','Distinguere un output prodotto da un risultato accettato alla qualità richiesta.'],['Confrontare i costi completi','Dividere il costo totale del periodo per le attività completate e accettate, con lo stesso perimetro.']],boundary:'Il risultato dipende dai costi inclusi, dal periodo osservato e dai criteri di accettazione. Non dimostra da solo un ritorno sull’investimento.',actions:[['Leggi il quadro di governance ed economia','governance'],['Esamina i cambiamenti con ARGOS','argos']]}
    }
  });

  Object.assign(UI.en,{gallery:'All visual guides',png:'Download PNG',pdf:'Download PDF for LinkedIn',busy:'Preparing the file…',error:'The file could not be created. Please try again.',prepared:'The file is ready. If the download did not start, use this link.',save:'Save the file'});
  Object.assign(UI.fr,{gallery:'Tous les schémas',png:'Télécharger le PNG',pdf:'Télécharger le PDF pour LinkedIn',busy:'Préparation du fichier…',error:'Le fichier n’a pas pu être créé. Réessayez.',prepared:'Le fichier est prêt. Si le téléchargement n’a pas démarré, utilisez ce lien.',save:'Enregistrer le fichier'});
  Object.assign(UI.it,{gallery:'Tutti gli schemi',png:'Scarica il PNG',pdf:'Scarica il PDF per LinkedIn',busy:'Preparazione del file…',error:'Non è stato possibile creare il file. Riprova.',prepared:'Il file è pronto. Se il download non è iniziato, usa questo link.',save:'Salva il file'});
  const entries = document.querySelectorAll('[data-voce-diagram]');
  if (!entries.length) return;
  const dialog = document.createElement('dialog');
  if (typeof dialog.showModal !== 'function') return;
  dialog.className = 'vg-dialog';
  dialog.id = 'voce-visual-guide';
  dialog.setAttribute('aria-labelledby', 'vg-title');
  dialog.setAttribute('aria-describedby', 'vg-description');
  document.body.append(dialog);
  let opener = null;
  let activeKey = null;
  let exportLoader = null;
  let exportUrl = null;
  let renderToken = 0;
  function lang() {
    const l = (document.documentElement.lang || 'en').slice(0,2).toLowerCase();
    return Object.prototype.hasOwnProperty.call(UI,l) ? l : 'en';
  }
  function esc(v) {
    return String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  function href(route,l) {
    if (route.startsWith('#')) return '/'+route;
    const localized=['agent-infrastructure','agent-conformance','argos','human-cognitive-assurance','governance','atlas','visual-guides'];
    const base=route.split('#')[0];
    return (l !== 'en' && localized.includes(base) ? '/'+l : '')+'/'+route;
  }
  function clearExport() {
    if(exportUrl) URL.revokeObjectURL(exportUrl);
    exportUrl=null;
  }
  function exporter() {
    if(!exportLoader) exportLoader=import('/visual-guide-export.js?v=20261011').catch(error=>{exportLoader=null;throw error;});
    return exportLoader;
  }
  function render(key) {
    renderToken++;
    clearExport();
    const l=lang(),ui=UI[l],guide=GUIDES[key],copy=guide[l];
    dialog.lang=l;
    const stages=copy.stages.map((s,i)=>'<li class="vg-stage">'+(guide.type==='map'?'':'<span class="vg-number">'+(guide.type==='levels'?'A'+i:String(i+1).padStart(2,'0'))+'</span>')+'<h3>'+esc(s[0])+'</h3><p>'+esc(s[1])+'</p>'+(s[2]?'<p class="vg-human"><strong>'+esc(ui.human)+'</strong>'+esc(s[2])+'</p>':'')+'</li>').join('');
    const proof=guide.proof?'<section class="vg-detail"><h3>'+esc(ui.proof)+'</h3><ol class="vg-proof-states">'+ui.states.map(s=>'<li><strong>'+esc(s[0])+'</strong>'+esc(s[1])+'</li>').join('')+'</ol></section>':'';
    dialog.innerHTML='<div class="vg-header"><p class="vg-brand">VOCE</p><button type="button" class="vg-close" data-vg-close>'+esc(ui.close)+'</button></div><div class="vg-body"><p class="vg-kicker">'+esc(ui.kicker)+'</p><h2 class="vg-title" id="vg-title" tabindex="-1">'+esc(copy.title)+'</h2><p class="vg-intro" id="vg-description">'+esc(copy.intro)+'</p><ol class="vg-stages'+(guide.type==='levels'?' vg-stages--levels':'')+'">'+stages+'</ol>'+proof+'<p class="vg-boundary">'+esc(copy.boundary)+'</p><div class="vg-actions">'+copy.actions.map(a=>'<a href="'+esc(href(a[1],l))+'">'+esc(a[0])+'</a>').join('')+'<a href="'+href('visual-guides',l)+'">'+esc(ui.gallery)+'</a></div><div class="vg-exports"><button type="button" data-vg-export="png">'+esc(ui.png)+'</button><button type="button" data-vg-export="pdf">'+esc(ui.pdf)+'</button><p class="vg-export-status" role="status" aria-live="polite"></p></div><p class="vg-source">'+esc(ui.source)+'</p></div>';
  }
  function sync() {
    const ui=UI[lang()];
    try{localStorage.setItem('voce-lang',lang());}catch{}
    entries.forEach(a=>a.textContent=ui.open);
    if(dialog.open && activeKey) render(activeKey);
  }
  entries.forEach(a=>{
    a.setAttribute('aria-haspopup','dialog');
    a.setAttribute('aria-controls',dialog.id);
    a.addEventListener('click',event=>{
      const key=a.dataset.voceDiagram;
      if (!Object.prototype.hasOwnProperty.call(GUIDES,key)) return;
      // Preserve normal modified-link navigation and the HTML fallback.
      if(event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || event.button>0) return;
      render(key);
      try { dialog.showModal(); } catch { return; }
      event.preventDefault();
      opener=a;activeKey=key;
      document.body.classList.add('voce-visual-is-open');
      dialog.querySelector('#vg-title').focus({preventScroll:true});
    });
  });
  dialog.addEventListener('click',async event=>{
    const exportButton=event.target.closest('[data-vg-export]');
    if(exportButton && activeKey) {
      const token=renderToken,l=lang(),ui=UI[l],key=activeKey,guide=GUIDES[key];
      const buttons=dialog.querySelectorAll('[data-vg-export]');
      const status=dialog.querySelector('.vg-export-status');
      buttons.forEach(b=>b.disabled=true);
      status.textContent=ui.busy;
      try {
        const module=await exporter();
        const format=exportButton.dataset.vgExport;
        const blob=await module.createExport({key,lang:l,guide,copy:guide[l],ui},format);
        if(token!==renderToken || !dialog.open) return;
        clearExport();
        exportUrl=URL.createObjectURL(blob);
        const link=document.createElement('a');
        link.href=exportUrl;link.download='VOCE-'+key+'-'+l+'.'+format;link.textContent=ui.save;
        status.textContent=ui.prepared+' ';status.append(link);
        link.click();
      } catch {
        if(token===renderToken) status.textContent=ui.error;
      } finally {
        if(token===renderToken) buttons.forEach(b=>b.disabled=false);
      }
      return;
    }
    if(event.target.closest('[data-vg-close]') || event.target.closest('.vg-actions a')) {
      dialog.close();
      return;
    }
    if(event.target===dialog){
      const r=dialog.getBoundingClientRect();
      if(event.clientX<r.left || event.clientX>r.right || event.clientY<r.top || event.clientY>r.bottom) dialog.close();
    }
  });
  dialog.addEventListener('close',()=>{
    renderToken++;
    clearExport();
    document.body.classList.remove('voce-visual-is-open');
    activeKey=null;
    if(opener?.isConnected) opener.focus({preventScroll:true});
  });
  new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
  sync();
})();
